1	// Probe helper: run the reference Python executable over a JSON corpus and show
2	// its exact output. Lets discovery agents study behaviour without fighting shell
3	// quoting.
4	//
5	// Usage:  node /workspace/harness/probe.mjs <corpus.json>
6	//         node /workspace/harness/probe.mjs --inline '["SELECT 1; SELECT 2"]'
7	//
8	// Entries are either a string (argv becomes ["--a", s]) or an array of raw argv.
9	
10	import { spawnSync } from 'node:child_process';
11	import { readFileSync } from 'node:fs';
12	
13	const EXE = '/workspace/dataset/test2_executable';
14	const args = process.argv.slice(2);
15	
16	let entries;
17	if (args[0] === '--inline') entries = JSON.parse(args[1]);
18	else entries = JSON.parse(readFileSync(args[0], 'utf8'));
19	
20	for (const entry of entries) {
21	  const argv = Array.isArray(entry) ? entry.map(String) : ['--a', String(entry)];
22	  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 });
23	  console.log('IN   : ' + JSON.stringify(argv));
24	  console.log('OUT  : ' + JSON.stringify(r.stdout ?? ''));
25	  if (r.stderr) console.log('ERR  : ' + JSON.stringify(r.stderr));
26	  console.log('CODE : ' + r.status);
27	  console.log('');
28	}
29

1	// Differential test harness: compares the Python executable against the Node port.
2	//
3	// Usage:
4	//   node /workspace/harness/compare.mjs <corpus.json> [--impl /output/test2.mjs] [--quiet] [--max N]
5	//
6	// Corpus format: JSON array whose entries are either
7	//   - a string           -> argv becomes ["--a", <string>]
8	//   - an array of strings -> used verbatim as argv
9	//
10	// Compares stdout, stderr and exit code byte-for-byte and prints every mismatch
11	// with fully escaped payloads so nothing is lost to shell quoting.
12	
13	import { spawnSync } from 'node:child_process';
14	import { readFileSync } from 'node:fs';
15	
16	const EXE = '/workspace/dataset/test2_executable';
17	
18	const rawArgs = process.argv.slice(2);
19	let corpusPath = null;
20	let impl = '/output/test2.mjs';
21	let quiet = false;
22	let max = Infinity;
23	for (let i = 0; i < rawArgs.length; i++) {
24	  const a = rawArgs[i];
25	  if (a === '--impl') impl = rawArgs[++i];
26	  else if (a === '--quiet') quiet = true;
27	  else if (a === '--max') max = Number(rawArgs[++i]);
28	  else corpusPath = a;
29	}
30	if (!corpusPath) {
31	  console.error('usage: node compare.mjs <corpus.json> [--impl path] [--quiet] [--max N]');
32	  process.exit(64);
33	}
34	
35	const entries = JSON.parse(readFileSync(corpusPath, 'utf8'));
36	if (!Array.isArray(entries)) {
37	  console.error('corpus must be a JSON array');
38	  process.exit(64);
39	}
40	
41	const run = (cmd, args) => {
42	  const r = spawnSync(cmd, args, { encoding: 'utf8', maxBuffer: 1 << 28 });
43	  if (r.error) return { out: '', err: String(r.error), code: -999 };
44	  return { out: r.stdout ?? '', err: r.stderr ?? '', code: r.status === null ? -1 : r.status };
45	};
46	
47	// argparse prints the program name in usage/error text; normalise it so only
48	// real behavioural differences are reported.
49	const normalise = (s) => s.split('test2_executable').join('PROG').split('test2.mjs').join('PROG');
50	
51	let pass = 0;
52	const fails = [];
53	let n = 0;
54	for (const entry of entries) {
55	  if (n >= max) break;
56	  n++;
57	  const argv = Array.isArray(entry) ? entry.map(String) : ['--a', String(entry)];
58	  const expected = run(EXE, argv);
59	  const actual = run('node', [impl, ...argv]);
60	  const same =
61	    expected.out === actual.out &&
62	    normalise(expected.err) === normalise(actual.err) &&
63	    expected.code === actual.code;
64	  if (same) pass++;
65	  else fails.push({ argv, expected, actual });
66	}
67	
68	if (!quiet) {
69	  for (const f of fails) {
70	    console.log('================ MISMATCH ================');
71	    console.log('argv     : ' + JSON.stringify(f.argv));
72	    console.log('exp.out  : ' + JSON.stringify(f.expected.out));
73	    console.log('act.out  : ' + JSON.stringify(f.actual.out));
74	    if (normalise(f.expected.err) !== normalise(f.actual.err)) {
75	      console.log('exp.err  : ' + JSON.stringify(f.expected.err));
76	      console.log('act.err  : ' + JSON.stringify(f.actual.err));
77	    }
78	    if (f.expected.code !== f.actual.code) {
79	      console.log('exp.code : ' + f.expected.code + '   act.code : ' + f.actual.code);
80	    }
81	  }
82	}
83	console.log(`\nRESULT: ${pass}/${n} passed, ${fails.length} failed  (corpus=${corpusPath})`);
84	process.exit(fails.length === 0 ? 0 : 1);
85

