const fs = require('fs');
const cases = [];
// END + <C> : split  <=>  C is NOT an identifier-continuation (\w) char
const suffix = [
  'ǅ','ʰ','ᴬ','ก','०','０','ↀ','²','௰',
  '̃','ः','‿','€','©','😀','𝐀','­',
  'µ','々','༳','½','⁰','ꧏ','Ⅰ','〇','ー','ː',
];
for (const c of suffix) cases.push('( END' + c + '; SELECT 2;');
// whitespace-before-dot test: no split <=> C counts as \s for the (?=\s*\.) lookahead
const ws = [' ','	','
','',' ','','','','','',
            '',' ',' ',' ',' ',' ',' ',' ','　','​','﻿'];
for (const c of ws) cases.push('( END' + c + '.a; SELECT 2;');
// END <ws> IF multiword
for (const c of [' ','	','
','',' ',' ','　','']) {
  cases.push('CREATE p BEGIN END' + c + 'IF; SELECT 2;');
}
cases.push('CREATE p BEGIN END  IF; SELECT 2;');
cases.push('CREATE p BEGIN END/*c*/IF; SELECT 2;');
cases.push('CREATE p BEGIN END LOOP; SELECT 2;');
cases.push('CREATE p BEGIN END WHILE; SELECT 2;');
cases.push('CREATE p BEGIN END FOR; SELECT 2;');
cases.push('CREATE p BEGIN END CASE; SELECT 2;');
cases.push('CREATE p BEGIN END IF ; SELECT 2;');
cases.push('CREATE p BEGIN END IF(); SELECT 2;');
cases.push('CREATE p BEGIN END IF.a; SELECT 2;');
cases.push('CREATE p BEGIN END IF$; SELECT 2;');
fs.writeFileSync('/workspace/corpus/tmp-batch5.json', JSON.stringify(cases, null, 1));
console.log(cases.length);
EOF
node /workspace/gen5.cjs && node /workspace/harness/probe.mjs /workspace/corpus/tmp-batch5.json 2>&1 | grep -E "^(IN|OUT)"

